CREATE DATABASE IF NOT EXISTS barkodda_bela CHARACTER SET utf8mb4 COLLATE utf8mb4_turkish_ci;
USE barkodda_bela;
SET FOREIGN_KEY_CHECKS=0;
DROP TABLE IF EXISTS player_achievements,achievements,player_upgrades,upgrades,customer_encounters,customers,player_inventory,products,game_saves,player_profiles,users;
SET FOREIGN_KEY_CHECKS=1;
CREATE TABLE users(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,username VARCHAR(40) NOT NULL UNIQUE,email VARCHAR(190) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,settings_json JSON NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,last_login DATETIME NULL) ENGINE=InnoDB;
CREATE TABLE player_profiles(user_id INT UNSIGNED PRIMARY KEY,current_night INT NOT NULL DEFAULT 1,personal_money INT NOT NULL DEFAULT 0,market_money INT NOT NULL DEFAULT 2500,market_level INT NOT NULL DEFAULT 1,reputation INT NOT NULL DEFAULT 50,suspicion INT NOT NULL DEFAULT 0,knowledge_points INT NOT NULL DEFAULT 0,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE game_saves(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id INT UNSIGNED NOT NULL,save_slot TINYINT NOT NULL DEFAULT 1,game_state JSON NOT NULL,current_night INT NOT NULL DEFAULT 1,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,UNIQUE KEY uq_save(user_id,save_slot),FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE products(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name_tr VARCHAR(80),name_en VARCHAR(80),category VARCHAR(40),purchase_price DECIMAL(8,2),sale_price DECIMAL(8,2),shelf_life INT DEFAULT 0,unlock_level INT DEFAULT 1) ENGINE=InnoDB;
CREATE TABLE player_inventory(user_id INT UNSIGNED,product_id INT UNSIGNED,quantity INT DEFAULT 0,expiry_data JSON NULL,PRIMARY KEY(user_id,product_id),FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,FOREIGN KEY(product_id) REFERENCES products(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE customers(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(80),customer_type VARCHAR(30),danger_level TINYINT DEFAULT 0,dialogue_data JSON,anomaly_data JSON) ENGINE=InnoDB;
CREATE TABLE customer_encounters(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id INT UNSIGNED,customer_id INT UNSIGNED,night_number INT,decision VARCHAR(30),result VARCHAR(30),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,FOREIGN KEY(customer_id) REFERENCES customers(id)) ENGINE=InnoDB;
CREATE TABLE upgrades(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(80),category VARCHAR(40),price INT,required_level INT DEFAULT 1,effect_data JSON) ENGINE=InnoDB;
CREATE TABLE player_upgrades(user_id INT UNSIGNED,upgrade_id INT UNSIGNED,level INT DEFAULT 1,PRIMARY KEY(user_id,upgrade_id),FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,FOREIGN KEY(upgrade_id) REFERENCES upgrades(id)) ENGINE=InnoDB;
CREATE TABLE achievements(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name_tr VARCHAR(100),name_en VARCHAR(100),description_tr VARCHAR(255),condition_data JSON) ENGINE=InnoDB;
CREATE TABLE player_achievements(user_id INT UNSIGNED,achievement_id INT UNSIGNED,unlocked_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(user_id,achievement_id),FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,FOREIGN KEY(achievement_id) REFERENCES achievements(id)) ENGINE=InnoDB;
